"""Private, write-once storage for original documents.

Design rules (see docs/phases/PHASE-2A-PLAN.md):

* Keys are generated by the server from UUIDs only (:class:`BlobKey`). No file name or other
  client-supplied text ever reaches a key, so path traversal is impossible by construction.
* ``put_new`` is create-only: it fails if the key exists and never overwrites.
* There is **no delete** operation. The application cannot remove an original; cleanup is an
  operator action under the retention policy (D10).
"""

from __future__ import annotations

import os
import re
import shutil
import tempfile
import uuid
from dataclasses import dataclass
from pathlib import Path
from typing import IO, Protocol

import anyio.to_thread
from azure.core.exceptions import ResourceExistsError, ResourceNotFoundError
from azure.storage.blob import BlobServiceClient, ContentSettings

from meip.core.config import BlobBackend, Settings

_UUID = r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
BLOB_KEY_PATTERN = rf"^{_UUID}/{_UUID}/{_UUID}/{_UUID}/original$"
_BLOB_KEY = re.compile(BLOB_KEY_PATTERN)
_COPY_CHUNK = 1024 * 1024


class BlobExistsError(Exception):
    """A create-only write found the key already present."""


class BlobNotFoundError(Exception):
    """No blob is stored under the key."""


@dataclass(frozen=True)
class BlobKey:
    """A validated storage key: ``{tenant}/{case}/{document}/{version}/original``."""

    value: str

    def __post_init__(self) -> None:
        if not _BLOB_KEY.fullmatch(self.value):
            raise ValueError("not a valid blob key")

    @classmethod
    def original(
        cls, tenant_id: uuid.UUID, case_id: uuid.UUID, document_id: uuid.UUID, version_id: uuid.UUID
    ) -> BlobKey:
        return cls(f"{tenant_id}/{case_id}/{document_id}/{version_id}/original")


class BlobStore(Protocol):
    """Create-only, read-only-after-write storage. Deliberately has no delete."""

    async def put_new(self, key: BlobKey, source: IO[bytes]) -> None:
        """Store ``source`` (read from its current position) under a new key."""
        ...

    async def read_into(self, key: BlobKey, sink: IO[bytes]) -> None:
        """Copy the stored bytes into ``sink``."""
        ...

    async def list_keys(self) -> list[str]:
        """Every stored key (operator reporting only)."""
        ...


class FilesystemBlobStore:
    """A local directory. Writes go to a temporary file that is then hard-linked into place,
    so a key appears atomically and an existing key is never replaced."""

    def __init__(self, root: Path) -> None:
        self._root = root.resolve()

    def _path(self, key: BlobKey) -> Path:
        path = (self._root / key.value).resolve()
        if not path.is_relative_to(self._root):  # unreachable for a valid key; defence in depth
            raise ValueError("blob key escapes the storage root")
        return path

    def _put(self, key: BlobKey, source: IO[bytes]) -> None:
        target = self._path(key)
        target.parent.mkdir(parents=True, exist_ok=True)
        fd, temp_name = tempfile.mkstemp(dir=target.parent, prefix=".incoming-")
        try:
            with os.fdopen(fd, "wb") as temp:
                shutil.copyfileobj(source, temp, _COPY_CHUNK)
                temp.flush()
                os.fsync(temp.fileno())
            try:
                os.link(temp_name, target)  # fails if the target exists: never overwrites
            except FileExistsError as exc:
                raise BlobExistsError(key.value) from exc
        finally:
            Path(temp_name).unlink(missing_ok=True)  # the temporary name, never the target

    def _read(self, key: BlobKey, sink: IO[bytes]) -> None:
        try:
            with self._path(key).open("rb") as stored:
                shutil.copyfileobj(stored, sink, _COPY_CHUNK)
        except FileNotFoundError as exc:
            raise BlobNotFoundError(key.value) from exc

    def _list(self) -> list[str]:
        if not self._root.exists():
            return []
        return sorted(
            p.relative_to(self._root).as_posix()
            for p in self._root.rglob("original")
            if p.is_file()
        )

    async def put_new(self, key: BlobKey, source: IO[bytes]) -> None:
        await anyio.to_thread.run_sync(self._put, key, source)

    async def read_into(self, key: BlobKey, sink: IO[bytes]) -> None:
        await anyio.to_thread.run_sync(self._read, key, sink)

    async def list_keys(self) -> list[str]:
        return await anyio.to_thread.run_sync(self._list)


class AzureBlobStore:
    """Azure Blob Storage through the official SDK's synchronous client, run in a worker
    thread (the async client would add aiohttp as a dependency). The container is private:
    no public access, and no SAS URLs are issued to browsers."""

    def __init__(self, connection_string: str, container: str) -> None:
        self._service = BlobServiceClient.from_connection_string(connection_string)
        self._container = self._service.get_container_client(container)

    def _put(self, key: BlobKey, source: IO[bytes]) -> None:
        try:
            self._container.upload_blob(
                key.value,
                source,
                overwrite=False,
                content_settings=ContentSettings(content_type="application/octet-stream"),
            )
        except ResourceExistsError as exc:
            raise BlobExistsError(key.value) from exc

    def _read(self, key: BlobKey, sink: IO[bytes]) -> None:
        try:
            self._container.download_blob(key.value).readinto(sink)
        except ResourceNotFoundError as exc:
            raise BlobNotFoundError(key.value) from exc

    def _list(self) -> list[str]:
        return sorted(blob.name for blob in self._container.list_blobs())

    def _ensure_container(self) -> bool:
        try:
            self._container.create_container(public_access=None)  # private: no anonymous reads
        except ResourceExistsError:
            return False
        return True

    async def put_new(self, key: BlobKey, source: IO[bytes]) -> None:
        await anyio.to_thread.run_sync(self._put, key, source)

    async def read_into(self, key: BlobKey, sink: IO[bytes]) -> None:
        await anyio.to_thread.run_sync(self._read, key, sink)

    async def list_keys(self) -> list[str]:
        return await anyio.to_thread.run_sync(self._list)

    def _public_access(self) -> str | None:
        return self._container.get_container_properties().public_access

    async def public_access(self) -> str | None:
        """The container's anonymous access level; ``None`` means private."""
        return await anyio.to_thread.run_sync(self._public_access)

    async def ensure_container(self) -> bool:
        """Create the private container if missing (local bootstrap only; IaC in Azure)."""
        return await anyio.to_thread.run_sync(self._ensure_container)


def build_blob_store(settings: Settings) -> BlobStore:
    if settings.blob_backend is BlobBackend.FILESYSTEM:
        return FilesystemBlobStore(settings.blob_root)
    if settings.blob_connection_string is None:
        raise ValueError("blob_connection_string is not configured")
    return AzureBlobStore(
        settings.blob_connection_string.get_secret_value(), settings.blob_container
    )


def orphaned_keys(stored: list[str], recorded: set[str]) -> list[str]:
    """Stored blobs with no database row: left by a crash between storing a blob and
    committing its row. Reported for an operator; never deleted by the application."""
    return [key for key in stored if key not in recorded]
